package app.bsuite.configuracion.common;
import app.bsuite.configuracion.common.constantes.BSMensajes;
import app.bsuite.configuracion.common.model.ConceptoProductoVO;
import app.bsuite.test.BsuiteTest;
import faf.app.base.data.db.DBHelperManager;
import faf.app.base.data.db.iface.DBHelper;
import faf.app.base.exceptions.FunctionalException;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
public class ConceptoProductoHLPTest extends BsuiteTest {
private ConceptoProductoVO concepto;
private ConceptoProductoHLP hlp;
private DBHelper dbh;
@BeforeAll
void setupOnce() throws Exception {
hlp = new ConceptoProductoHLP();
dbh = DBHelperManager.getInstance().getDBHelper(getSession());
}
@BeforeEach
void setup() throws Exception {
concepto = createConceptoProductoVO();
}
@Test
void canUpdateWithProductoVenta() throws Exception {
concepto.setEsProductoVenta(true);
assertTrue(hlp.canInsert(concepto, dbh));
}
@Test
void canUpdateWithProductoCompra() throws Exception {
concepto.setEsProductoCompra(true);
assertTrue(hlp.canInsert(concepto, dbh));
}
@Test
void canUpdateWithProductoLogistica() throws Exception {
concepto.setEsProductoLogistica(true);
assertTrue(hlp.canInsert(concepto, dbh));
}
@Test
void canUpdateWithoutProductoTipo() {
FunctionalException exception = assertThrows(FunctionalException.class, () -> {
hlp.canInsert(concepto, dbh);
});
assertEquals(BSMensajes.FALTA_TIPO_CONCEPTO_PRODUCTO, exception.getDetalle());
}
@Test
void insertOK() throws Exception {
generateMocksEntidad();
Long resultado = hlp.insert(concepto, dbh);
assertEquals(resultado, 1L);
}
private ConceptoProductoVO createConceptoProductoVO() throws FunctionalException {
ConceptoProductoVO retorna = new ConceptoProductoVO(getSession().getCryptedSessionID());
// Los tipos de productos se inicializan en 'false' para modificarlos en los tests necesarios.
retorna.setEsProductoVenta(false);
retorna.setEsProductoCompra(false);
retorna.setEsProductoLogistica(false);
return retorna;
}
}

Configurar testeo unitario en servicios de Springboot
Paso a Paso:
Configurar dependencias al proyecto
Springboot cuenta con un paquete de testeo como dependencia que podemos agregar como dependencia al pom.xml de nuestro proyecto:
<dependency>
<groupId>org.springframework.boot</groupId>
<artifactId>spring-boot-starter-test</artifactId>
<scope>test</scope>
</dependency>
Este paquete cuenta con las siguientes dependencias integradas para el testeo unitario de spring:
JUnit 5+ (paquete de testeo unitario para java)
Assertj (assertions)
Mockito (para realizar mocking de clases)
Creación de carpeta para test
Para que se puedan correr los tests unitarios que escribamos es necesario saber donde están. Por convención las clases que creemos deben estar en una carpeta llamada test/java/ de nuestra carpeta src.
Si nos encontramos con que nuestro proyecto no tiene creada esta carpeta, es necesario crearla.
Nuestro proyecto debe quedar de la siguiente manera:
+-- pom.xml
+-- src/
+-- main/
|     +-- java/
+-- test/
+-- java/
+-- TestExample.java
Configuración de clases de testeo
Para crear casos de test es necesario que sean métodos de una clase. Es recomendable que el nombre de las clases que creemos tengan el prefijo o sufijo “test”:
Test*.java
*Test.java
Para los servicios de Springboot necesitamos anotar nuestra clase con la anotación
@SpringBootTest
(classes = …) donde classes representa el nombre de la clase de nuestra aplicación(la que contiene la anotación
@SpringBootApplication
).
Esta anotación hace que el test se corra dentro de un contexto de spring con el que vamos a usar las anotaciones como
@Autowired
y que spring se encargue de inyectar las dependencias de nuestros controladora, servicio, repositorios, etc.
import org.springframework.boot.test.context.SpringBootTest;
import org.junit.jupiter.api.*;
@SpringBootTest(classes = MiServicioApplication.class)
public class TestMiServicio {
@Test
public void listar_todos() {
// Lógica de testeo
}
}
Creación de métodos de test
Los casos de test que creemos se escriben en los métodos de la clase. Cada método tiene que tener la anotación
@Test
. Solo los métodos que contengan esta anotación van a ser reconocidos y ejecutados como tests.
Los test unitarios funcionan mediante assertions, que es una condición que marcamos que se tiene que cumplir durante el test. Las assertions más comunes que podemos usar pertenecen a junit, las cuales son métodos estáticos de la clase
org.junit.jupiter.api.Assertions
@SpringBootTest(classes = MiServicioApplication.class)
class TestMiServicio {
@Test
public void test_update(){
Usuario user = new Usuario();
user.setNombre("123");
controller.update(user);
User savedUser = controller.get(user.getId());
assertTrue("123", savedUser.getNombre());
}
}
Armado de Mocks con Mockito
La librería mockito nos permite hacer mocks de objetos que retornan valores que nosotros definamos en lugar de los originales.
Esto puede resultarnos útil a la hora de testear un comportamiento que requiere datos que se devuelvan de otro servicio o de una base de datos ya que podemos hacer que al llamar a los métodos que devuelven los datos se devuelvan los valores que nosotros definamos.
Spring contiene la anotación
@MockBean
con la que podemos reemplazar el
@Autowired
y crear automáticamente un mock de un Bean de spring, gracias a eso podemos crear mocks de controladores, servicios, repositorios
class TestMiServicio {
@MockBean
UsersRepository usersRepository;
// Esta anotación hace que este método se ejecute antes de cada test
@BeforeEach
public void antesDeCadaTest() {
// Mock de un método que devuelve un valor
when(usersRepository.getUser(anyString())).thenAnswer( (in) -> {return FakeData.getUser(in.getArgument(0));} );
// Mock de un método void
doAnswer((in) -> {
FakeData.saveFakeUser(in.getArgument(0));
return null;
}).when(federadoRepository).save(any());
}
@Autowired
MyController controller;
@Test
public final test_save() {
// Cuando el controlador intente llamar al método saveUser del repositorio mockeado, va a ejecutarse FakeData.saveFakeUser() en su lugar
boolean success = controller.save_user(new User());
assertTrue(success);
}
}

